def order(ed):
    cfirst=set()
    for parity in range(2):
        cohort=range(1+parity,9,2)
        cfirst.update(sorted(cohort,key=lambda i:hashlib.sha256(seed+b'\0'+ed.encode()+b'\0'+str(i).encode()).digest())[:2])
    return [{'pair':i,'direction':'original-to-edit' if i%2 else 'edit-to-original','order':['C','A'] if i in cfirst else ['A','C']} for i in range(1,9)]
